<script setup lang="ts">import{apiErrorMessage}from'~/utils/api-error';useHead({title:'Proposer un projet'});const form=reactive({organizationName:'',contactName:'',email:'',phone:'',territory:'',audience:'',issue:'',proposalType:'',timeframe:'',budget:'',participantCount:'',comment:''});const pending=ref(false);const successMessage=ref('');const errorMessage=ref('');async function submit(){pending.value=true;successMessage.value='';errorMessage.value='';try{await $fetch('/api/public/proposals',{method:'POST',body:{...form,budget:form.budget||null,participantCount:form.participantCount||null}});successMessage.value='Votre proposition a été transmise à IFICS. Elle sera qualifiée avant toute création de projet interne.';Object.assign(form,{organizationName:'',contactName:'',email:'',phone:'',territory:'',audience:'',issue:'',proposalType:'',timeframe:'',budget:'',participantCount:'',comment:''})}catch(error){errorMessage.value=apiErrorMessage(error,'Impossible d’envoyer la proposition.')}finally{pending.value=false}}</script>
<template><section class="section"><div class="container proposal"><div><p class="eyebrow">Proposer un projet</p><h1 class="section-title">Décrivez le besoin avant de parler solution.</h1><p class="lead">Votre demande arrive dans un espace de qualification interne. IFICS peut ensuite vous contacter, approfondir le besoin et, si la proposition est retenue, la convertir en projet sans ressaisie.</p></div><form class="card card-pad" @submit.prevent="submit"><div v-if="successMessage" class="alert alert-success" role="status">{{successMessage}}</div><div v-if="errorMessage" class="alert alert-error" role="alert">{{errorMessage}}</div><div class="form-grid"><div class="field"><label for="organization">Organisation *</label><input id="organization" v-model="form.organizationName" class="input" required></div><div class="field"><label for="contact-name">Contact *</label><input id="contact-name" v-model="form.contactName" class="input" required></div><div class="field"><label for="proposal-email">E-mail *</label><input id="proposal-email" v-model="form.email" class="input" type="email" required></div><div class="field"><label for="proposal-phone">Téléphone</label><input id="proposal-phone" v-model="form.phone" class="input" type="tel"></div><div class="field"><label for="territory">Territoire</label><input id="territory" v-model="form.territory" class="input"></div><div class="field"><label for="audience">Public concerné</label><input id="audience" v-model="form.audience" class="input"></div><div class="field field-full"><label for="issue">Besoin / problématique *</label><textarea id="issue" v-model="form.issue" class="textarea" minlength="20" required></textarea></div><div class="field"><label for="proposal-type">Type d’action envisagé</label><input id="proposal-type" v-model="form.proposalType" class="input"></div><div class="field"><label for="timeframe">Période / calendrier</label><input id="timeframe" v-model="form.timeframe" class="input"></div><div class="field"><label for="budget">Budget indicatif (€)</label><input id="budget" v-model="form.budget" class="input" inputmode="decimal"></div><div class="field"><label for="participants">Nombre de participants</label><input id="participants" v-model="form.participantCount" class="input" type="number" min="0"></div><div class="field field-full"><label for="proposal-comment">Informations complémentaires</label><textarea id="proposal-comment" v-model="form.comment" class="textarea"></textarea></div></div><button class="btn btn-primary" type="submit" :disabled="pending">{{pending?'Envoi…':'Transmettre la proposition'}}</button></form></div></section></template>
<style scoped>.proposal{display:grid;grid-template-columns:.75fr 1.25fr;gap:45px;align-items:start}form{display:flex;flex-direction:column;gap:20px}@media(max-width:850px){.proposal{grid-template-columns:1fr}}</style>
